"""Private object-class loader aliases, without changing the sealed daemon tool tree."""
import pathlib,subprocess,rbd
from ceph_cluster_native import PrivateCeph

class PrivateRBD(PrivateCeph):
 def __enter__(self):
  super().__enter__()
  try:
   classes=self.root/'object-classes';classes.mkdir()
   source=pathlib.Path('/opt/opsforge-ceph/usr/lib/x86_64-linux-gnu/rados-classes')
   for library in sorted(source.glob('*.so*')):
    alias=classes/(library.name.split('.so',1)[0]+'.so')
    if not alias.exists():alias.symlink_to(library)
   self.config.write_text(self.config.read_text().replace(str(source),str(classes)))
   version=subprocess.run(['rbd','--version'],capture_output=True,text=True,timeout=10)
   assert version.returncode==0 and 'ceph version 16.2.15 ' in version.stdout
   return self
  except BaseException:
   import sys
   super().__exit__(*sys.exc_info());raise

def create(api,io,name,size=16*1024*1024):
 api.create(io,name,size,order=22,old_format=False,features=rbd.RBD_FEATURE_LAYERING)
